import { useEffect, useRef, useState, type RefObject } from 'react'
import Lenis from 'lenis'
import { ScrollTrigger, gsap, prefersReduced, setLenis, useGsap } from './lib/gsap'
import { useLang } from './lib/i18n'
import { ReadyCtx } from './lib/ready'
import { scrollToHash } from './lib/scroll'
import { Header } from './components/Header'
import { Footer } from './components/Footer'
import { Loader } from './components/Loader'
import { JourneyRail } from './components/JourneyRail'
import Home from './pages/Home'
import { Work, workCategories } from './sections/Work'

function useReveals(scope: RefObject<HTMLElement | null>, deps: unknown[], enabled: boolean) {
  useGsap(scope, () => {
    if (!enabled || prefersReduced()) return
    gsap.utils.toArray<HTMLElement>('[data-reveal]').forEach((el) => {
      const delay = Number(el.dataset.delay ?? 0)
      const scrollTrigger = { trigger: el, start: 'top 90%', once: true }
      switch (el.dataset.reveal) {
        case 'lines':
          gsap.to(el.querySelectorAll('.line-inner'), { y: 0, duration: 1.25, ease: 'expo.out', stagger: 0.1, delay, scrollTrigger })
          break
        case 'blur':
          gsap.to(el, { opacity: 1, filter: 'blur(0px)', scale: 1, duration: 1.3, ease: 'power3.out', delay, scrollTrigger })
          break
        case 'clip':
          gsap.to(el, { clipPath: 'inset(0 0 0% 0)', duration: 1.4, ease: 'expo.inOut', delay, scrollTrigger })
          break
        case 'rule':
          gsap.to(el, { scaleX: 1, duration: 1.2, ease: 'expo.out', delay, scrollTrigger })
          break
        default:
          gsap.to(el, { opacity: 1, y: 0, duration: 1.1, ease: 'expo.out', delay, scrollTrigger })
      }
    })
  }, deps)
}

// Normal links load each page at its own URL; no extra routing package is needed.
export default function App() {
  const { switching, tr, rtl } = useLang()
  const [ready, setReady] = useState(false)
  const main = useRef<HTMLElement>(null)
  const path = typeof window === 'undefined' ? '/' : window.location.pathname.replace(/\/+$/, '') || '/'
  const isHome = path === '/'
  const match = path.match(/^\/work\/([^/]+)$/)
  const category = workCategories.find((item) => item.id === match?.[1])

  useEffect(() => {
    if (prefersReduced() || window.matchMedia('(pointer: coarse)').matches) return
    const lenis = new Lenis({ duration: 1.1 })
    setLenis(lenis)
    if (import.meta.env.DEV) (window as unknown as { __lenis: Lenis }).__lenis = lenis
    lenis.on('scroll', ScrollTrigger.update)
    const tick = (t: number) => lenis.raf(t * 1000)
    gsap.ticker.add(tick)
    gsap.ticker.lagSmoothing(0)
    return () => {
      gsap.ticker.remove(tick)
      lenis.destroy()
      setLenis(null)
    }
  }, [])

  useEffect(() => {
    let cancelled = false
    const refresh = () => { if (!cancelled) ScrollTrigger.refresh() }
    const id = window.setTimeout(refresh, 350)
    document.fonts?.ready.then(refresh)
    window.addEventListener('load', refresh)
    return () => {
      cancelled = true
      window.clearTimeout(id)
      window.removeEventListener('load', refresh)
    }
  }, [])

  useEffect(() => {
    if (!ready) return
    const id = window.setTimeout(() => {
      ScrollTrigger.refresh()
      if (window.location.hash) scrollToHash(window.location.hash)
    }, 400)
    return () => window.clearTimeout(id)
  }, [ready])

  // Existing header/footer section links should return to the homepage.
  useEffect(() => {
    if (isHome) return
    const links = Array.from(document.querySelectorAll<HTMLAnchorElement>('a[href^="#"]'))
      .filter((link) => !main.current?.contains(link) && link.hash !== '#main')
    const originals = links.map((link) => [link, link.getAttribute('href')!] as const)
    originals.forEach(([link, href]) => link.setAttribute('href', `/${href}`))
    const goHome = (event: MouseEvent) => {
      const link = event.target instanceof Element ? event.target.closest<HTMLAnchorElement>('a') : null
      if (!link || !links.includes(link) || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return
      event.preventDefault()
      event.stopPropagation()
      window.location.assign(link.href)
    }
    document.addEventListener('click', goHome, true)
    return () => {
      document.removeEventListener('click', goHome, true)
      originals.forEach(([link, href]) => link.setAttribute('href', href))
    }
  }, [isHome, switching])

  useReveals(main, [ready], ready)

  return (
    <ReadyCtx.Provider value={ready}>
      <Loader onDone={() => setReady(true)} />
      <Header />
      <main ref={main} id="main" tabIndex={-1} className={`page-enter lang-fade outline-none ${switching ? 'is-switching' : ''}`}>
        {isHome ? <Home /> : category ? <Work categoryId={category.id} /> : (
          <section dir={rtl ? 'rtl' : 'ltr'} className="min-h-[70vh] bg-[#051746] px-6 pb-24 pt-40 text-center text-white">
            <h1 className="text-4xl font-semibold">{tr({ en: 'Page not found', ar: 'الصفحة غير موجودة' })}</h1>
            <a href="/" className="mt-8 inline-flex gap-3 rounded-full bg-[#f6620d] px-6 py-3">
              <span aria-hidden="true">{rtl ? '→' : '←'}</span>
              {tr({ en: 'Back to home', ar: 'العودة إلى الصفحة الرئيسية' })}
            </a>
          </section>
        )}
      </main>
      <div className={`lang-fade ${switching ? 'is-switching' : ''}`}><Footer /></div>
      {isHome && <JourneyRail />}
    </ReadyCtx.Provider>
  )
}
